def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = None

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            identifiers = prerelease.split('.')
            for ident in identifiers:
                if ident.isdigit():
                    prerelease_identifiers.append((0, int(ident)))
                else:
                    prerelease_identifiers.append((1, ident))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease_ids = parse_version(v)
        # For sorting: versions with prerelease come before those without
        # A version without prerelease is "greater" than with prerelease
        # So we use (major, minor, patch, has_prerelease, prerelease_ids)
        # where has_prerelease=True means no prerelease (sorts after)
        has_no_prerelease = len(prerelease_ids) == 0

        return (major, minor, patch, has_no_prerelease, prerelease_ids)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

